import type { Feature, FeatureCollection, MultiPolygon, Position } from 'geojson';
import type { LatLng } from './MapView.types';

export type BoundaryCollection = FeatureCollection<MultiPolygon>;

/** Generated by `python -m pomorie.reference.boundary`; served from app/public. */
export const BOUNDARY_URL = '/pomorie_boundary.geojson';

export async function loadBoundary(): Promise<BoundaryCollection> {
  const response = await fetch(BOUNDARY_URL);
  if (!response.ok) throw new Error(`boundary request failed: ${response.status}`);
  return (await response.json()) as BoundaryCollection;
}

/** Ray casting: count how many ring edges a ray going east from the point crosses. */
function ringContains(ring: Position[], lng: number, lat: number): boolean {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    if (yi > lat !== yj > lat && lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) {
      inside = !inside;
    }
  }
  return inside;
}

/** True if the point is inside any polygon's outer ring and not inside one of its holes. */
export function boundaryContains(feature: Feature<MultiPolygon>, { lat, lng }: LatLng): boolean {
  return feature.geometry.coordinates.some(
    ([outer, ...holes]) =>
      ringContains(outer, lng, lat) && !holes.some((hole) => ringContains(hole, lng, lat)),
  );
}

/** Large rectangle with the municipality cut out, used to shade everything outside it. */
export function outsideMask(feature: Feature<MultiPolygon>): Feature {
  const world: Position[] = [[26, 41], [29, 41], [29, 44], [26, 44], [26, 41]];
  const holes = feature.geometry.coordinates.map(([outer]) => outer);
  return { type: 'Feature', properties: {}, geometry: { type: 'Polygon', coordinates: [world, ...holes] } };
}
